/**
 * packages/web/public/evidence/evidence.json: the sponsor evidence page data (neatlogs, Entire,
 * cfo.ai). Generated by `notary export --evidence` from facts on disk, never typed by hand:
 *   - neatlogs "live" only if a `notary doctor` success is recorded (config/neatlogs-doctor.json);
 *     a trace link only if a trace link template exists (src/trace/links.ts), else the id stays text.
 *   - Entire "live" only if `entire` is on PATH AND a checkpoint ref exists in git
 *     (refs/entire/checkpoints/*, or the legacy entire/checkpoints/* branch).
 *   - cfo.ai "live" only once a cfo.ai plan is imported (economics.json carries a non-null `plan`).
 * The facts are also written to packages/core/config/evidence-facts.json (committed), so evidence.json
 * can be checked on a fresh clone: some facts come from local-only state that `git clone` does not
 * bring (gitignored runs/<runId>/spans.jsonl, refs/entire/checkpoints, what is on PATH). Those are
 * LOCAL_FACT_KEYS; the rest are derived from committed files and re-derivable anywhere.
 * Schema rules: exactly the three sponsors, status "live" | "pending", and only links that exist
 * (https, no placeholders, never the private GitHub repo). test/publish.test.ts validates the file.
 */
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";
import { findOnPath } from "../beliefs/evidence.js";
import { DoctorRecordSchema, readDoctorRecord, type DoctorRecord } from "../trace/doctor.js";
import { resolveTraceLinkTemplate, traceLinkFor, type TemplateSource } from "../trace/links.js";
import { collectBundles } from "./collect.js";

export const EVIDENCE_PATH = fileURLToPath(new URL("../../../web/public/evidence/evidence.json", import.meta.url));
/** The facts evidence.json was generated from (written by `notary export --evidence`, committed). */
export const EVIDENCE_FACTS_PATH = fileURLToPath(new URL("../../config/evidence-facts.json", import.meta.url));
const WEB_BUNDLES_INDEX = fileURLToPath(new URL("../../../web/public/bundles/index.json", import.meta.url));

export const SPONSOR_NAMES = ["neatlogs", "Entire", "cfo.ai"] as const;

/** Text that marks a link as invented or unfinished. */
export const PLACEHOLDER_URL = /example\.(com|org|net)|localhost|127\.0\.0\.1|placeholder|todo|tbd|xxx|changeme|your[-_]|<|>|\{|\}/i;

/** The project repo is private; it is mentioned in notes, never offered as public evidence. */
export const PRIVATE_REPO_URL = "https://github.com/parthchilwerwar/notary";

export const EvidenceLinkSchema = z
  .object({
    label: z.string().min(1),
    url: z.url({ protocol: /^https$/ }),
  })
  .strict()
  .refine((l) => !PLACEHOLDER_URL.test(l.url), { message: "placeholder link" })
  .refine((l) => !l.url.toLowerCase().startsWith(PRIVATE_REPO_URL), { message: "the project repo is private; not public evidence" });

export const SponsorEvidenceSchema = z
  .object({
    name: z.enum(SPONSOR_NAMES),
    purpose: z.string().min(20),
    status: z.enum(["live", "pending"]),
    links: z.array(EvidenceLinkSchema),
    notes: z.string().min(1),
  })
  .strict();

export const EvidenceSchema = z
  .array(SponsorEvidenceSchema)
  .length(SPONSOR_NAMES.length)
  .refine((xs) => SPONSOR_NAMES.every((n) => xs.filter((x) => x.name === n).length === 1), { message: "each sponsor exactly once" });

export type SponsorEvidence = z.infer<typeof SponsorEvidenceSchema>;

export function loadEvidence(path: string = EVIDENCE_PATH): SponsorEvidence[] {
  return EvidenceSchema.parse(JSON.parse(readFileSync(path, "utf8")));
}

// ------------------------------------------------------------------ generator

const REPO_ROOT = fileURLToPath(new URL("../../../../", import.meta.url));
const CORE_RUNS_DIR = fileURLToPath(new URL("../../runs/", import.meta.url));

export const NEATLOGS_SDK_LINK = { label: "neatlogs TypeScript SDK (source)", url: "https://github.com/neatlogs/neatlogs-typescript" };
export const ENTIRE_DOCS_LINK = { label: "Entire docs: entire graph command reference (DECISIONS #61)", url: "https://docs.entire.io/cli-reference/graph" };

/** Everything the sponsor statuses are derived from. */
export interface EvidenceFacts {
  /** Published real bundles (public/bundles/index.json) whose traceLinks name at least one trace; undefined = not counted. */
  publishedTraceLinks?: number | undefined;
  /** Last successful `notary doctor` (config/neatlogs-doctor.json), if any. */
  doctor?: DoctorRecord | undefined;
  /** Trace link template, if one is configured. */
  traceTemplate: TemplateSource;
  /** Traces marked exported in the spans.jsonl of FINISHED real runs (exportedRunTraceIds). */
  exportedRunTraces: number;
  neatlogsCliOnPath: boolean;
  entire: { onPath: boolean; checkpointRefs: string[] };
  businessPlan: boolean;
  economicsJson: boolean;
  /** packages/web/public/economics.json carries an imported cfo.ai plan (`plan` not null). */
  cfoPlanImported?: boolean;
}

/** Facts that come from local-only state a fresh `git clone` does not have (see the file header). */
export const LOCAL_FACT_KEYS = ["exportedRunTraces", "neatlogsCliOnPath", "entire"] as const;

export const EvidenceFactsSchema = z
  .object({
    publishedTraceLinks: z.number().int().nonnegative().optional(),
    doctor: DoctorRecordSchema.optional(),
    traceTemplate: z.object({ template: z.string().optional(), source: z.enum(["env", "config", "none"]), problem: z.string().optional(), derivedAt: z.string().optional() }).strict(),
    exportedRunTraces: z.number().int().nonnegative(),
    neatlogsCliOnPath: z.boolean(),
    entire: z.object({ onPath: z.boolean(), checkpointRefs: z.array(z.string()) }).strict(),
    businessPlan: z.boolean(),
    economicsJson: z.boolean(),
    cfoPlanImported: z.boolean().optional(),
  })
  .strict();

const EvidenceFactsFileSchema = z.object({ schema: z.literal("notary-evidence-facts/1"), facts: EvidenceFactsSchema }).strict();

/** The committed facts snapshot (undefined when it does not exist). */
export function readEvidenceFacts(path: string = EVIDENCE_FACTS_PATH): EvidenceFacts | undefined {
  if (!existsSync(path)) return undefined;
  return EvidenceFactsFileSchema.parse(JSON.parse(readFileSync(path, "utf8"))).facts as EvidenceFacts;
}

/** Published real bundles whose traceLinks name at least one trace (public/bundles/index.json). */
export function publishedTraceLinkCount(indexPath: string = WEB_BUNDLES_INDEX): number | undefined {
  if (!existsSync(indexPath)) return undefined;
  const dir = dirname(indexPath);
  let n = 0;
  try {
    for (const e of JSON.parse(readFileSync(indexPath, "utf8")) as { runId?: unknown; sample?: unknown }[]) {
      if (e.sample !== false || typeof e.runId !== "string" || !/^[A-Za-z0-9._-]+$/.test(e.runId)) continue;
      const file = join(dir, `${e.runId}.json`);
      if (!existsSync(file)) continue;
      const links = (JSON.parse(readFileSync(file, "utf8")) as { traceLinks?: unknown }).traceLinks;
      if (links && typeof links === "object" && Object.keys(links).length > 0) n += 1;
    }
  } catch {
    return undefined;
  }
  return n;
}

/** True when the published economics.json holds an imported cfo.ai plan. */
function cfoPlanImported(path: string): boolean {
  try {
    const raw = JSON.parse(readFileSync(path, "utf8")) as { plan?: unknown };
    return raw.plan !== null && raw.plan !== undefined;
  } catch {
    return false;
  }
}

/**
 * Git refs that hold Entire checkpoints: one ref per checkpoint under refs/entire/checkpoints/ (the
 * default `git-refs` store of Entire CLI 0.11.x), or the legacy entire/checkpoints/* branch, local or remote.
 */
export function entireCheckpointRefs(repoRoot: string = REPO_ROOT): string[] {
  try {
    const out = execFileSync("git", ["for-each-ref", "--format=%(refname)", "refs/heads", "refs/remotes", "refs/entire"], {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
    return out
      .split(/\r?\n/)
      .map((l) => l.trim())
      // Not refs/heads/entire/<sha7>-<hash6>: that is a live session's shadow branch, not a checkpoint.
      .filter((r) => /^refs\/(heads|remotes\/[^/]+)\/entire\/checkpoints\//.test(r) || /^refs\/entire\/checkpoints\//.test(r))
      .sort();
  } catch {
    return [];
  }
}

/**
 * Trace ids marked `exported: true` in runs/<dir>/spans.jsonl, counted only for FINISHED real runs:
 * the dir must hold a hash-verified, non-sample bundle (export/collect.ts collectBundles). A run still
 * in progress (spans are appended as it goes; its bundle is written at the end), a sample or fixture
 * run, or a stray spans file does not count. Counting every spans.jsonl let any keyed CLI run in
 * progress elsewhere on the machine (.env carries a real NEATLOGS_API_KEY, so its spans are marked
 * exported) change these facts mid-way, racing test/publish.test.ts's committed-file check.
 */
export function exportedRunTraceIds(runsDir: string = CORE_RUNS_DIR): Set<string> {
  const out = new Set<string>();
  if (!existsSync(runsDir)) return out;
  for (const { file } of collectBundles(runsDir).bundles) {
    const spans = join(runsDir, dirname(file), "spans.jsonl");
    if (!existsSync(spans)) continue;
    let text: string;
    try {
      text = readFileSync(spans, "utf8");
    } catch {
      continue;
    }
    for (const line of text.split(/\r?\n/)) {
      if (!line.includes('"exported":true')) continue;
      try {
        const rec = JSON.parse(line) as { traceId?: unknown; exported?: unknown };
        if (rec.exported === true && typeof rec.traceId === "string") out.add(rec.traceId.toLowerCase());
      } catch {
        // skip malformed lines
      }
    }
  }
  return out;
}

export function gatherEvidenceFacts(
  opts: { env?: NodeJS.ProcessEnv; repoRoot?: string; runsDir?: string; doctorRecordPath?: string; configPath?: string; bundlesIndexPath?: string } = {},
): EvidenceFacts {
  const env = opts.env ?? process.env;
  const root = opts.repoRoot ?? REPO_ROOT;
  const entireOnPath = findOnPath("entire", env) !== undefined;
  const traceLinks = publishedTraceLinkCount(opts.bundlesIndexPath ?? join(root, "packages", "web", "public", "bundles", "index.json"));
  return {
    ...(traceLinks !== undefined ? { publishedTraceLinks: traceLinks } : {}),
    doctor: readDoctorRecord(opts.doctorRecordPath),
    traceTemplate: resolveTraceLinkTemplate({ env, ...(opts.configPath ? { configPath: opts.configPath } : {}) }),
    exportedRunTraces: exportedRunTraceIds(opts.runsDir ?? CORE_RUNS_DIR).size,
    neatlogsCliOnPath: findOnPath("neatlogs-cli", env) !== undefined,
    entire: { onPath: entireOnPath, checkpointRefs: entireOnPath ? entireCheckpointRefs(root) : [] },
    businessPlan: existsSync(join(root, "docs", "BUSINESS.md")),
    economicsJson: existsSync(join(root, "packages", "web", "public", "economics.json")),
    cfoPlanImported: cfoPlanImported(join(root, "packages", "web", "public", "economics.json")),
  };
}

function day(iso: string): string {
  const d = new Date(iso.length === 10 ? `${iso}T00:00:00Z` : iso);
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
}

function neatlogsEntry(f: EvidenceFacts): SponsorEvidence {
  const purpose =
    "The neatlogs TypeScript SDK (1.1.26) wraps every queue item, recon step, probe and model call in a span via withSpan (AGENT, TOOL, GUARDRAIL and EVALUATOR spans; DECISIONS #204); probe spans carry the prediction committed before the call. Model calls go through LiteLLM and are captured with the SDK's wrapOpenAI (wrapBedrock when the provider is Bedrock). Every span is also written to runs/<runId>/spans.jsonl, which the evidence checks read. `pnpm notary doctor` reads the recorded doctor trace back from neatlogs (GET <ingest>/api/traces/v3/<traceId> with the project key).";
  const links: SponsorEvidence["links"] = [{ ...NEATLOGS_SDK_LINK }];
  const d = f.doctor;
  if (!d) {
    return {
      name: "neatlogs",
      purpose,
      status: "pending",
      links,
      notes:
        "No recorded `notary doctor` success (packages/core/config/neatlogs-doctor.json is missing), so no span is known to have reached neatlogs. Run `pnpm notary doctor` with NEATLOGS_API_KEY set. No published bundle links a trace (traceLinks are empty).",
    };
  }
  const traceUrl = traceLinkFor(d.traceId, f.traceTemplate.template);
  if (traceUrl) links.push({ label: "neatlogs trace of the `notary doctor` smoke span", url: traceUrl });
  const cite = d.source.includes("DECISIONS #93") ? "; DECISIONS #93" : "";
  const parts = [
    `Status "live" covers SDK export only: on ${day(d.flushedAt)}, with NEATLOGS_API_KEY set, \`pnpm notary doctor\` flushed one real span and the SDK reported the flush as successful (trace ${d.traceId}, span ${d.spanId}${cite}).`,
    f.exportedRunTraces === 0
      ? "That smoke span is the only one exported so far: no notarize or run spans have reached neatlogs, because those commands have not run live."
      : `Beyond that smoke span, ${f.exportedRunTraces} notarize/run trace(s) are marked exported in local spans.jsonl files.`,
  ];
  const readBack = `Read-back uses the traces API, not the CLI (neatlogs-cli is ${f.neatlogsCliOnPath ? "installed" : "not installed"}): \`pnpm notary doctor\` fetches the recorded doctor trace with the project key and prints its span counts; that result is printed, not recorded in a file, so it is not shown here (DECISIONS #204 records one real read-back).`;
  const links_ = f.publishedTraceLinks === undefined ? "" : f.publishedTraceLinks === 0 ? " No published bundle links a trace (their traceLinks are empty)." : ` ${f.publishedTraceLinks} published bundle(s) link a trace.`;
  if (traceUrl) {
    const from =
      f.traceTemplate.source === "env"
        ? "NEATLOGS_TRACE_URL_TEMPLATE"
        : `packages/core/config/neatlogs.json (derived from a real trace URL${f.traceTemplate.derivedAt ? ` on ${day(f.traceTemplate.derivedAt)}` : ""})`;
    parts.push(`${readBack} The trace link comes from the template in ${from}.${links_}`);
  } else {
    parts.push(`${readBack} The neatlogs trace URL format is unknown, so there is no trace link.${links_}`);
  }
  return { name: "neatlogs", purpose, status: "live", links, notes: parts.join(" ") };
}

function entireEntry(f: EvidenceFacts): SponsorEvidence {
  const purpose =
    "Entire checkpoints the AI agent sessions that write this repo: with `entire enable --agent claude-code`, every commit made during a Claude Code session carries an Entire-Checkpoint trailer linking it to that session's transcript, prompts and files touched. The adversary's session backend is a headless Claude Code review whose verdict is committed, so each review is checkpointed next to its belief. `notary guards coverage --backend entire` runs one `entire graph edges` pass and fails on any caller of a money-moving tool method outside the guard wrapper. packages/web/public/evidence/entire.json (`notary export --entire`) lists the checkpoints and the coverage result.";
  const links: SponsorEvidence["links"] = [{ ...ENTIRE_DOCS_LINK }];
  const privateRepo = "The project repo (github.com/parthchilwerwar/notary) is private, so the checkpoint history is not public.";
  if (!f.entire.onPath) {
    return {
      name: "Entire",
      purpose,
      status: "pending",
      links,
      notes: `The Entire CLI is not installed on the machine that generated this file: no checkpoints can be read, and guard coverage falls back to the tsc backend. Install it (docs/ENTIRE.md), then run \`entire enable --agent claude-code\` and \`entire plugin install graph\`. ${privateRepo}`,
    };
  }
  if (f.entire.checkpointRefs.length === 0) {
    return {
      name: "Entire",
      purpose,
      status: "pending",
      links,
      notes: `The Entire CLI is on PATH, but no checkpoint exists yet (no ref under refs/entire/checkpoints and no entire/checkpoints branch). A checkpoint is created by the first commit made while Entire tracks a Claude Code session in this repo. ${privateRepo}`,
    };
  }
  // Namespaces, not every ref: the git-refs store adds one ref per checkpoint.
  const where = [...new Set(f.entire.checkpointRefs.map((r) => (r.startsWith("refs/entire/checkpoints/") ? "refs/entire/checkpoints" : r)))].join(", ");
  return {
    name: "Entire",
    purpose,
    status: "live",
    links,
    notes: `The Entire CLI is on PATH and checkpoints exist (${where}); \`notary export --entire\` lists them in packages/web/public/evidence/entire.json with their sessions, commits and files touched. ${privateRepo}`,
  };
}

function cfoEntry(f: EvidenceFacts): SponsorEvidence {
  const purpose = "Business plan: pricing per monitored API contract, COGS from bundle credits and tokens, the cost of incidents prevented, and runway.";
  if (!f.businessPlan) {
    const missing = f.economicsJson ? "docs/BUSINESS.md does not exist yet (packages/web/public/economics.json does)" : "neither exists yet";
    return {
      name: "cfo.ai",
      purpose,
      status: "pending",
      links: [],
      notes: `Not started. Planned for P10 as a manual step that produces docs/BUSINESS.md and packages/web/public/economics.json; ${missing}.`,
    };
  }
  if (!f.cfoPlanImported) {
    return {
      name: "cfo.ai",
      purpose,
      status: "pending",
      links: [],
      notes: `docs/BUSINESS.md exists and \`notary economics\` exports the real run costs for cfo.ai (export/cfo-inputs.csv), but no cfo.ai plan has been imported yet (\`pnpm notary economics --cfo-import <file>\`).`,
    };
  }
  return {
    name: "cfo.ai",
    purpose,
    status: "live",
    links: [],
    notes: `A cfo.ai plan is imported; docs/BUSINESS.md exists${f.economicsJson ? " and packages/web/public/economics.json is published" : "; packages/web/public/economics.json does not exist yet"}. The repo is private, so the plan is not linked.`,
  };
}

/** The sponsor evidence derived from `facts` (pure; validated against EvidenceSchema). */
export function buildEvidence(facts: EvidenceFacts = gatherEvidenceFacts()): SponsorEvidence[] {
  return EvidenceSchema.parse([neatlogsEntry(facts), entireEntry(facts), cfoEntry(facts)]);
}

/** `notary export --evidence`: regenerate evidence.json from facts on disk, and record those facts. */
export function writeEvidence(opts: { path?: string; facts?: EvidenceFacts; factsPath?: string | null } = {}): { path: string; evidence: SponsorEvidence[]; lines: string[] } {
  const path = opts.path ?? EVIDENCE_PATH;
  const facts = opts.facts ?? gatherEvidenceFacts();
  const evidence = buildEvidence(facts);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `${JSON.stringify(evidence, null, 2)}\n`, "utf8");
  // Default: the committed snapshot for the published file; next to `path` for any other output.
  const factsPath = opts.factsPath !== undefined ? opts.factsPath : opts.path === undefined ? EVIDENCE_FACTS_PATH : join(dirname(path), "evidence-facts.json");
  if (factsPath) {
    const file = EvidenceFactsFileSchema.parse({ schema: "notary-evidence-facts/1", facts: JSON.parse(JSON.stringify(facts)) });
    mkdirSync(dirname(factsPath), { recursive: true });
    writeFileSync(factsPath, `${JSON.stringify(file, null, 2)}\n`, "utf8");
  }
  const lines = [
    `evidence: ${path}`,
    ...(factsPath ? [`facts: ${factsPath}`] : []),
    ...evidence.map((e) => `  ${e.name}: ${e.status} (${e.links.length} link${e.links.length === 1 ? "" : "s"})`),
  ];
  return { path, evidence, lines };
}
